function stateFrom(kv) {
  return {
    filterRanks: allRanks().map((r) => r.id).filter((id) => kv[`filter_${id}`] === "1"),
    onlineOnly: kv.filter_online === "1",
    search: kv.role_search || ""
  };
}
function checked(kv, prefix) {
  return allRanks().map((r) => r.id).filter((id) => kv[`${prefix}${id}`] === "1");
}
function refreshRankHolders(ctx, rankId) {
  for (const s of ctx.sessions) {
    if (rankOf(s.account) === rankId) {
      ctx.sendCharacterState(s);
      broadcastNameChanged(s);
    }
  }
}
function handleRolesDialog(ctx, session, kv) {
  if (!mayManageRanks(session)) return true;
  const btn = (kv.buttonClicked || "").trim();
  if (btn === "role_tab_ranks") {
    openRanksTab(ctx, session);
    return true;
  }
  if (btn === "role_tab_players") {
    openPlayersTab(ctx, session);
    return true;
  }
  if (btn === "role_tab_create") {
    openCreateRankDialog(session);
    return true;
  }
  return true;
}
function handleRanksTab(ctx, session, kv) {
  if (!mayManageRanks(session)) return true;
  const btn = (kv.buttonClicked || "").trim();
  if (btn === "role_back") {
    openRolesDialog(ctx, session);
    return true;
  }
  if (btn.startsWith("role_open_")) {
    openRankEditorDialog(ctx, session, btn.slice("role_open_".length));
    return true;
  }
  return true;
}
function handlePlayersTab(ctx, session, kv) {
  if (!mayManageRanks(session)) return true;
  const btn = (kv.buttonClicked || "").trim();
  if (btn === "role_back") {
    openRolesDialog(ctx, session);
    return true;
  }
  if (btn === "role_apply_filter") {
    openPlayersTab(ctx, session, stateFrom(kv));
    return true;
  }
  if (btn.startsWith("role_player_")) {
    openPlayerRoleDialog(ctx, session, Number(btn.slice("role_player_".length)));
    return true;
  }
  return true;
}
function handleRankEditorDialog(ctx, session, kv) {
  if (!mayManageRanks(session)) return true;
  const btn = (kv.buttonClicked || "").trim();
  if (btn === "role_back") {
    openRanksTab(ctx, session);
    return true;
  }
  if (btn.startsWith("role_save_")) {
    const id = btn.slice("role_save_".length);
    if (!rankExists(id)) return true;
    const mine = actorLevel(session);
    if (rankDef(id).level > mine) {
      OnConsoleMessage(session, "`4You cannot edit a rank above your own level.``");
      openRanksTab(ctx, session);
      return true;
    }
    const patch = {};
    const label = CLEAN(kv.role_label);
    const prefix = CLEAN(kv.role_prefix);
    const color = CLEAN(kv.role_color);
    const level = CLEAN(kv.role_level);
    if (label) patch.label = label;
    if (prefix) patch.prefix = prefix;
    if (color) patch.chatColor = color;
    if (level && /^\d+$/.test(level)) patch.level = Math.min(mine, Number(level));
    patch.permissions = ALL_PERMISSIONS.filter((p) => kv[`perm_${p}`] === "1" && hasPermission(session.account, p));
    const error = updateRank(id, patch);
    OnConsoleMessage(session, error ? `\`4${error}\`\`` : `Saved the ${id} rank.`);
    refreshRankHolders(ctx, id);
    openRanksTab(ctx, session);
    return true;
  }
  if (btn.startsWith("role_del_")) {
    const id = btn.slice("role_del_".length);
    if (!rankExists(id)) return true;
    if (rankDef(id).level >= actorLevel(session)) {
      OnConsoleMessage(session, "`4You cannot delete a rank at or above your own level.``");
      openRanksTab(ctx, session);
      return true;
    }
    const error = deleteRank(id);
    OnConsoleMessage(session, error ? `\`4${error}\`\`` : `Deleted the ${id} rank.`);
    openRanksTab(ctx, session);
    return true;
  }
  return true;
}
function handlePlayerRoleDialog(ctx, session, kv) {
  if (!mayManageRanks(session)) return true;
  const btn = (kv.buttonClicked || "").trim();
  if (btn === "role_back") {
    openPlayersTab(ctx, session);
    return true;
  }
  if (btn !== "role_apply_give") return true;
  const userId = Number(kv.role_uid || 0);
  const picked = checked(kv, "give_");
  if (!Number.isSafeInteger(userId) || !picked.length) {
    openPlayerRoleDialog(ctx, session, userId);
    return true;
  }
  const rankId = picked.sort((a, b) => rankDef(b).level - rankDef(a).level)[0];
  const account = [...ctx.accounts.values()].find((a) => a.userId === userId);
  if (!account) return true;
  if (!mayAssign(session, account, rankId)) {
    OnConsoleMessage(session, "`4You cannot give a rank at or above your own level.``");
    openPlayerRoleDialog(ctx, session, userId);
    return true;
  }
  applyRank(account, rankId);
  ctx.dirty = true;
  ctx.savePlayersNow();
  const online = [...ctx.sessions].find((s) => s.account.userId === userId);
  if (online) {
    ctx.sendCharacterState(online);
    broadcastNameChanged(online);
    OnConsoleMessage(online, `Your role is now ${fmtRank(rankId)} (Level ${rankDef(rankId).level}).`);
  }
  OnConsoleMessage(session, `You gave ${account.name} the ${fmtRank(rankId)} role.`);
  openPlayerRoleDialog(ctx, session, userId);
  return true;
}
function handleRoleManageDialog(ctx, session, dlg, kv) {
  if (!mayManageRanks(session)) return true;
  const btn = (kv.buttonClicked || "").trim();
  if (btn === "role_back") {
    openRanksTab(ctx, session);
    return true;
  }
  if (dlg !== "role_create" || btn !== "role_create_ok") return true;
  const id = (kv.role_id || "").toLowerCase().trim();
  const mine = actorLevel(session);
  const requested = /^d+$/.test((kv.role_level || "").trim()) ? Number(kv.role_level) : 0;
  const level = Math.min(mine, Math.max(0, requested));
  const prefix = CLEAN(kv.role_prefix) || "`w";
  const color = CLEAN(kv.role_color) || prefix;
  const label = CLEAN(kv.role_label) || id;
  const permissions = ALL_PERMISSIONS.filter((p) => kv[`perm_${p}`] === "1" && hasPermission(session.account, p));
  const error = createRank({ id, label, level, prefix, chatColor: color, permissions });
  OnConsoleMessage(session, error ? `\`4${error}\`\`` : `Created the ${prefix}${label}\`\` rank (id ${id}, level ${level}).`);
  openRanksTab(ctx, session);
  return true;
}
function handleRankCommand(ctx, session, cmd, parts, _argStr) {
  if (cmd === "ranks" || cmd === "rank") {
    if (!mayManageRanks(session)) return false;
    openRolesDialog(ctx, session);
    return true;
  }
  if (cmd === "setrank") {
    if (!mayManageRanks(session)) return false;
    const targetName = parts[1] || "";
    const rankId = (parts[2] || "").toLowerCase();
    const onlineTarget = ctx.findOnlineSessionByName(targetName);
    const account = onlineTarget?.account ?? ctx.accounts.get(targetName.toLowerCase());
    if (!targetName || !rankId || !rankExists(rankId) || !account) {
      OnConsoleMessage(session, "`4Unknown command.``  Enter `$/?`` for a list of valid commands.");
      return true;
    }
    if (!mayAssign(session, account, rankId)) {
      OnConsoleMessage(session, "`4You cannot give a rank at or above your own level.``");
      return true;
    }
    applyRank(account, rankId);
    ctx.dirty = true;
    ctx.savePlayersNow();
    const online = onlineTarget ?? [...ctx.sessions].find((s) => s.account === account);
    if (online) {
      ctx.sendCharacterState(online);
      broadcastNameChanged(online);
      OnConsoleMessage(online, `Your role is now ${fmtRank(rankId)} (Level ${rankDef(rankId).level}).`);
    }
    OnConsoleMessage(session, `You gave ${account.name} the ${fmtRank(rankId)} role.`);
    return true;
  }
  if (cmd === "rankreload") {
    if (!mayManageRanks(session)) return false;
    const count = reloadRanks(ctx.rootDir);
    for (const s of ctx.sessions) {
      ctx.sendCharacterState(s);
      broadcastNameChanged(s);
    }
    OnConsoleMessage(session, `Reloaded ${count} ranks.`);
    return true;
  }
  return false;
}

// server/action/dialog_return/index.ts
function handleDialogReturn(ctx, session, kv) {
  const dlg = (kv.dialog_name || "").trim();
  if (!dlg) return;
  const dlgLower = dlg.toLowerCase();
  if (dlgLower === "roles" || dlgLower === "role_ranks" || dlgLower === "role_players" || dlgLower === "role_rank" || dlgLower === "role_player" || dlgLower === "role_create") {
    if (!hasPermission(session.account, "setRanks")) return;
  }
  if (dlgLower === "roles") {
    handleRolesDialog(ctx, session, kv);
    return;
  }
  if (dlgLower === "role_ranks") {
    handleRanksTab(ctx, session, kv);
    return;
  }
  if (dlgLower === "role_players") {
    handlePlayersTab(ctx, session, kv);
    return;
  }
  if (dlgLower === "role_rank") {
    handleRankEditorDialog(ctx, session, kv);
    return;
  }
  if (dlgLower === "role_player") {
    handlePlayerRoleDialog(ctx, session, kv);
    return;
  }
  if (dlgLower === "role_create" || dlgLower === "role_edit" || dlgLower === "role_delete") {
    handleRoleManageDialog(ctx, session, dlgLower, kv);
    return;
  }
  if (dlg.toLowerCase() === "acceptaccess") {
    handleAcceptAccessDialog(ctx, session, kv);
    return;
  }
  if (dlg.toLowerCase() === "socialportal") {
    handleSocialPortalReturn(ctx, session, kv);
    return;
  }
  if (handleSdbDialogReturn(ctx, session, dlg, kv)) {
    return;
  }
  if (handleTelephoneLockeDialogReturn(ctx, session, dlg, kv)) {
    return;
  }
  if (dlg === "vending") {
    handleVendingDialogReturn(ctx, session, kv);
    return;
  }
  if (dlg === "statsblock") {
    handleGrowScanDialogReturn(ctx, session, kv);
    return;
  }
  if (dlg === "itemsucker_block") {
    handleSuckerDialogReturn(ctx, session, kv);
    return;
  }
  if (dlg === "growid_apply") {
    handleGrowIdApplyReturn(ctx, session, kv);
    return;
  }
  if (dlg === "drop_item") {
    handleDropItemReturn(ctx, session, kv);
    return;
  }
  if (dlg === "trash_item") {
    handleTrashItemReturn(ctx, session, kv);
    return;
  }
  if (dlg === "item_finder") {
    handleFindItemDialogReturn(ctx, session, kv);
    return;
  }
  if (handleWorldBlockDialogReturn(ctx, session, dlg, kv)) {
    return;
  }
  if (handleTileEditDialogReturn(ctx, session, dlg, kv)) {
    return;
  }
  handlePlayerDialogsReturn(ctx, session, dlg, kv);
}

// server/action/drop.ts
function handleDrop(ctx, session, kv) {
  const itemId = parseInt((kv.itemID || "0").trim(), 10);
  if (!itemId || itemId === 18 || itemId === 32) {
    OnPlayPositioned(session, "audio/punch_locked.wav");
    OnTextOverlay(session, "You'd be sorry if you lost that!");
    return;
  }
  const slot = session.account.inventory.find((s) => s.itemId === itemId && s.count > 0);
  if (!slot) return;
  const def = ctx.itemsDb.get(itemId);
  if (!def || isUntradeable(def)) {
    OnPlayPositioned(session, "audio/punch_locked.wav");
    OnTextOverlay(session, "You can't drop that.");
    return;
  }
  const world = session.world;
  if (!world) return;
  const playerTileX = Math.floor((session.x + 10) / 32);
  const playerTileY = Math.floor((session.y + 15) / 32);
  const targetTileX = Math.max(
    0,
    Math.min(world.width - 1, playerTileX + (session.facingLeft ? -1 : 1))
  );
  const targetTile = world.tiles[playerTileY * world.width + targetTileX];
  const targetFg = targetTile ? targetTile.fg : 0;
  const targetFgDef = targetFg ? ctx.itemsDb.get(targetFg) : void 0;
  if (targetFgDef) {
    const isSolid = targetFgDef.collisionType === 1;
    const isWhiteDoor = targetFg === 6 || targetFgDef.actionType === 13;
    const isEntrance = targetFgDef.isDoor || targetFgDef.actionType === 2 || targetFgDef.actionType === 13;
    const isClosedToggle = targetFgDef.actionType === 21 && (targetTile.flags & 64) === 0;
    if (isSolid || isWhiteDoor || isEntrance || isClosedToggle) {
      OnPlayPositioned(session, "audio/punch_locked.wav");
      OnTextOverlay(
        session,
        isWhiteDoor ? "You can't drop items on the white door." : "You can't drop that here, face somewhere with open space."
      );
      return;
    }
  }
  const name = stripGtColors(def.name);
  const dialog = new DialogBuilder().setDefaultColor("`o").addLabelWithIcon("big", `\`wDrop ${name}\`\``, itemId).addTextbox("How many to drop?").addTextInput("drop_count", "", String(slot.count), 5).embedData("itemID", itemId).endDialog("drop_item", "Cancel", "OK");
  OnDialogRequest(session, dialog);
}

// server/action/enter_game.ts
function handleEnterGame(ctx, session) {
  if (session.enteredGame) return;
  session.enteredGame = true;
  const acct = session.account;
  ctx.sendInventory(session, false);
  OnSetBux(session);
  OnEmoticonDataChanged(session);
  if (acct.isGuest) {
    SetHasGrowID(session, false, "", "");
  }
  const friendsCount = (acct.friendIds || []).length;
  const friendsOnline = (acct.friendIds || []).filter((id) => [...ctx.sessions].some((s) => s.account.userId === id)).length;
  const friendMsg = friendsCount === 0 ? "" : friendsOnline > 0 ? ` \`w${friendsOnline}\`\` friend is online.` : " No friends are online.";
  OnConsoleMessage(session, `Welcome back, \`w${acct.name}\`\`\`\`.${friendMsg}`);
  OnConsoleMessage(session, "`2Goals event``: Start working on your goals, you can be farmer, geiger hunter, take providers to receive prizes for leveling up. You will be able to claim your rewards at the end of the week!");
  OnConsoleMessage(session, "`3Limited time event``: 3x Gems from breaking blocks, Trees time reduced by 50%, Providers time reduced by 50%!");
  const day = (/* @__PURE__ */ new Date()).getDay();
  if (day === 1) OnConsoleMessage(session, "`3Today is Trees Day!`` 50% higher chance to get `2extra block`` from harvesting tree.");
  else if (day === 2) OnConsoleMessage(session, "`3Today is Breaking Day!`` 15% higher chance to get `2extra seed``.");
  else if (day === 3) OnConsoleMessage(session, "`3Today is Geiger Day!`` Higher chance of getting a `2better Geiger prize`` & Irradiated mod will last only `210 minutes``.");
  else if (day === 4) OnConsoleMessage(session, "`3Today is Tasks Day!`` Get extra `210`` points for completing a task.");
  else if (day === 5) OnConsoleMessage(session, "`3Today is Gems Day!`` 50% higher chance to get `2extra`` gem drop.");
  else if (day === 6) OnConsoleMessage(session, "`3Today is Surgery Day!`` Malpractice takes `215 minutes`` and Recovering takes `230 minutes`` & receive `2different prizes``.");
  else if (day === 0) OnConsoleMessage(session, "`3Today is Fishing Day!`` Catch a fish and receive `2extra lb``.");
  const recent = (acct.recentWorlds || []).filter((w) => isPlayableWorldName(w));
  const autoWorld = recent.length > 0 ? recent[0] : "START";
  ctx.joinWorld(session, autoWorld);
  RequestGazette(session);
  OnPlayPositioned(session, "audio/choir.wav", 400);
}

// server/action/info.ts
function handleInfo(ctx, session, kv) {
  const itemId = parseInt((kv.itemID || "0").trim(), 10);
  const def = ctx.itemsDb.get(itemId);
  if (!def || def.name.startsWith("null_")) return;
  const clean3 = stripGtColors(def.name);
  const dlg = new DialogBuilder().setDefaultColor("`o").addLabelWithIcon("big", `\`wAbout ${clean3}\`\``, def.id).addSpacer("small").addTextbox(`This is \`w${clean3}\`\` (Item ID \`#${def.id}\`\`).`);
  if (def.rarity && def.rarity < 999) {
    dlg.addSmalltext(`\`9Rarity: \`w${def.rarity}\`\``);
  }
  if (def.isSeed) {
    const mins = Math.floor((def.growTime || 0) / 60);
    const secs = (def.growTime || 0) % 60;
    dlg.addSmalltext(`\`9Grow Time: \`w${mins > 0 ? `${mins}m ` : ""}${secs}s\`\``);
  }
  if (def.isClothing) {
    const slotNames = [
      "Hair / Hat",
      "Shirt",
      "Pants",
      "Shoes",
      "Face",
      "Hand",
      "Back / Wings",
      "Mask",
      "Necklace",
      "Ancestral / Artifact"
    ];
    dlg.addSmalltext(`\`9Clothing Slot: \`w${slotNames[def.clothingType] || `Slot ${def.clothingType}`}\`\``);
  }
  dlg.addQuickExit();
  OnDialogRequest(session, dlg.endDialog("item_info", "Close", ""));
}

// server/commands/admin_commands.ts
function handleAdminCommand(ctx, session, cmd, parts, argStr) {
  if (["kick", "pull", "ban", "worldban", "unban", "worldunban", "uba"].includes(cmd)) {
    const world = session.world;
    if (!world) {
      OnConsoleMessage(session, "Enter a world first.");
      return true;
    }
    if (["unban", "worldunban", "uba"].includes(cmd)) {
      const allowed2 = world.ownerUserId === session.account.userId || hasPermission(session.account, "moderate") || world.tiles.some((t) => [242, 1796, 7188, 11550].includes(t.fg) && t.extra?.kind === "lock" && t.extra.adminIds.includes(session.account.userId));
      if (!allowed2) {
        OnConsoleMessage(session, "You cannot manage this world.");
        return true;
      }
      const query = (parts[1] || "").toLowerCase();
      if (!query && cmd === "uba") {
        world.worldBans = {};
        ctx.dirty = true;
        ctx.savePersistentState();
        OnConsoleMessage(session, "You've unbanned everybody from this world.");
        return true;
      }
      const exact = ctx.accounts.get(query), matches = [...ctx.accounts.values()].filter((a) => a.name.toLowerCase().startsWith(query));
      const acct = exact || (query && matches.length === 1 ? matches[0] : void 0);
      if (!acct) {
        OnConsoleMessage(session, "Player not found.");
        return true;
      }
      if (world.worldBans) delete world.worldBans[String(acct.userId)];
      ctx.dirty = true;
      ctx.savePersistentState();
      OnConsoleMessage(session, `${acct.name} is no longer world banned.`);
      return true;
    }
    const target = ctx.findOnlineSessionByName(parts[1] || "");
    if (!target || target.world !== world) {
      OnConsoleMessage(session, "Player is not in this world.");
      return true;
    }
    worldModerate(ctx, session, target, cmd === "pull" ? "pull" : cmd === "kick" ? "kick" : "worldban");
    return true;
  }
  if (cmd === "freeze" || cmd === "unfreeze") {
    if (!hasPermission(session.account, "moderate")) {
      OnConsoleMessage(session, "Moderator permission required.");
      return true;
    }
    const target = ctx.findOnlineSessionByName(parts[1] || "");
    if (!target || target.world !== session.world || !canModerate(session.account, target.account)) {
      OnConsoleMessage(session, "Player not found or protected.");
      return true;
    }
    if (cmd === "freeze") {
      if (isFrozen(target)) {
        OnConsoleMessage(session, "Player is frozen already.");
        return true;
      }
      target.account.playmods ??= [];
      target.account.playmods.push({ id: "gtps3-2", expiresAt: Date.now() + 15e3 });
      ctx.dirty = true;
      ctx.sendCharacterState(target);
      applySkinColorUpdate(target, false);
      OnConsoleMessage(target, "Your body has turned to ice. You can't move! (`$Frozen!`` mod added, `$15 seconds`` left)");
    } else {
      for (const mod of target.account.playmods || []) if (["gtps3-2", "gtps3-3", "gtps3-49"].includes(mod.id)) mod.expiresAt = Date.now() - 1;
      expireMods(ctx);
    }
    return true;
  }
  if (cmd === "give") {
    if (!hasPermission(session.account, "grantItems")) {
      OnConsoleMessage(session, "Developer permission required.");
      return true;
    }
    const target = ctx.findOnlineSessionByName(parts[1] || "");
    if (!target) {
      OnConsoleMessage(session, "Player not found.");
      return true;
    }
    const id = parseInt(parts[2] || "0", 10), qty = Math.max(1, Math.min(200, parseInt(parts[3] || "1", 10) || 1)), def = ctx.itemsDb.get(id);
    if (!def || def.name.startsWith("null_")) {
      OnConsoleMessage(session, "Invalid item ID.");
      return true;
    }
    const added = ctx.giveInventoryItem(target, id, qty, true);
    OnConsoleMessage(session, `Gave ${added}x ${stripGtColors(def.name)} to ${target.account.name}.`);
    return true;
  }
  if (cmd === "nick") {
    if (!hasPermission(session.account, "moderate")) {
      OnConsoleMessage(session, "Moderator permission required.");
      return true;
    }
    const newNick = argStr.replace(/[|\r\n\0]/g, "").trim();
    if (!newNick || newNick.toLowerCase() === session.account.name.toLowerCase()) {
      session.account.nickname = void 0;
      OnConsoleMessage(session, `Your name changed back to ${session.account.name}`);
    } else {
      session.account.nickname = newNick.slice(0, 24);
      OnConsoleMessage(session, `Your name changed to ${session.account.nickname}`);
    }
    ctx.dirty = true;
    ctx.savePlayersNow();
    broadcastNameChanged(session);
    return true;
  }
  if (cmd === "invis") {
    if (!hasPermission(session.account, "moderate")) {
      OnConsoleMessage(session, "Moderator permission required.");
      return true;
    }
    const nextInvis = !session.invis;
    session.invis = nextInvis;
    OnConsoleMessage(session, nextInvis ? "`oYou are now ninja, invisible at all." : "`oYou are once again visible to mortals.");
    const pkt = makeVariantPacket(["OnInvis", { type: "i32", value: nextInvis ? 1 : 0 }], session.netId);
    if (session.world) {
      for (const p of session.world.peers) p.peer.sendPacket(0, pkt, true);
    } else {
      session.peer.sendPacket(0, pkt, true);
    }
    return true;
  }
  return false;
}

