// server/action/trash.ts
function handleTrash(ctx, session, kv) {
  const itemId = parseInt((kv.itemID || "0").trim(), 10);
  if (!itemId || itemId === 18 || itemId === 32) {
    OnPlayPositioned(session, "audio/punch_locked.wav");
    OnTextOverlay(session, "You'd be sorry if you lost that!");
    return;
  }
  const slot = session.account.inventory.find((s) => s.itemId === itemId && s.count > 0);
  if (!slot) return;
  const def = ctx.itemsDb.get(itemId);
  if (!def || isUndestroyable(def)) {
    OnPlayPositioned(session, "audio/punch_locked.wav");
    OnTextOverlay(session, "You'd be sorry if you lost that!");
    return;
  }
  const name = stripGtColors(def.name);
  const dialog = new DialogBuilder().setDefaultColor("`o").addLabelWithIcon("big", `\`4Recycle\`\` \`w${name}\`\``, itemId).addTextbox(`How many to \`4destroy\`\`? (you have ${slot.count})`).addTextInput("count", "", String(slot.count), 5).embedData("itemID", itemId).endDialog("trash_item", "Cancel", "OK");
  OnDialogRequest(session, dialog);
}

// server/action/index.ts
function handleActionText(ctx, peer, rawText) {
  const kv = parseKvText(rawText);
  const session = peer.userData;
  if (!session) {
    if ("requestedName" in kv || "tankIDName" in kv || "protocol" in kv) {
      handleLogon(ctx, peer, kv);
    }
    return;
  }
  const action = (kv.action || "").trim();
  if (tradeAction(ctx, session, action, kv, rawText)) return;
  switch (action) {
    case "enter_game":
      handleEnterGame(ctx, session);
      return;
    case "growid":
      handleGrowIdAction(ctx, session, kv);
      return;
    case "join_request":
      handleJoinRequest(ctx, session, kv);
      return;
    case "quit_to_exit":
      handleQuitToExit(ctx, session);
      return;
    case "quit":
      handleQuit(ctx, session);
      return;
    case "refresh_item_data":
      handleRefreshItemData(ctx, session);
      return;
    case "respawn":
      handleRespawn(ctx, session, false);
      return;
    case "respawn_spike":
      handleRespawn(ctx, session, true);
      return;
    case "drop":
      handleDrop(ctx, session, kv);
      return;
    case "trash":
      handleTrash(ctx, session, kv);
      return;
    case "info":
      handleInfo(ctx, session, kv);
      return;
    case "wrench":
      handleWrenchPlayer(ctx, session, kv);
      return;
    case "trade_started":
      if (kv.netid) requestTrade(ctx, session, parseInt(kv.netid, 10));
      return;
    case "store":
    case "storenavigate":
      handleStore(ctx, session, kv.item || kv.selection || "main");
      return;
    case "buy":
      handleBuy(ctx, session, kv.item || "");
      return;
    case "friends":
      openSocialPortal(ctx, session, "Social");
      return;
    case "setSkin": {
      const raw = (kv.color || "").trim();
      const parsed = Number(raw);
      if (/^-?\d+$/.test(raw) && Number.isSafeInteger(parsed) && parsed >= -2147483648 && parsed <= 4294967295) setSkin(ctx, session, parsed >>> 0);
      return;
    }
    case "MagnoliaAppIWantANewFlag": {
      const cc = (kv.IWantTheFlagToBe || "").trim().toUpperCase();
      if (/^[A-Z]{2,4}$/.test(cc)) {
        session.account.flag = cc.toLowerCase();
        ctx.savePlayersNow();
        if (session.world) {
          broadcastTextOverlay(
            session.world,
            `action|MagnoliaAppIWantANewFlag
IWantTheFlagToBe|${cc}
netID|${session.netId}`
          );
        }
        OnConsoleMessage(session, `\`2Country flag set to \`w${cc}\`\`!`);
      }
      return;
    }
    case "dialog_return":
      handleDialogReturn(ctx, session, kv);
      return;
    case "input":
      handleInput(ctx, session, kv.text ?? "");
      return;
    case "killstore":
    case "setchatFilter":
      return;
    default:
      if (!action && rawText.trim()) {
        handleInput(ctx, session, rawText);
      }
      return;
  }
}

