// server/gamePacket/item_activate_object.ts
var GEM_ITEM_ID = 112;
function handleItemActivateObject(ctx, session, uid, forceDistance = false) {
  const world = session.world;
  if (!world) return;
  const idx = world.objects.findIndex((o) => o.uid === uid);
  if (idx === -1) return;
  const obj = world.objects[idx];
  if (!forceDistance && Math.hypot(session.x - obj.x, session.y - obj.y) > 160) return;
  if (isIllegalItem(ctx.itemsDb.get(obj.itemId)) && !hasPermission(session.account, "debug")) return;
  if (obj.itemId === GEM_ITEM_ID) {
    world.objects.splice(idx, 1);
    session.account.gems += obj.count;
    recordProgress(ctx, session, void 0, 0);
    ctx.dirty = true;
    ctx.savePlayersNow();
    const collectPkt2 = makeItemCollectPacket(session.netId, obj.uid);
    for (const p of world.peers) p.peer.sendPacket(0, collectPkt2, true);
    OnSetBux(session);
    return;
  }
  const existingSlot = session.account.inventory.find((s) => s.itemId === obj.itemId);
  let canTake = 0;
  if (existingSlot) {
    canTake = Math.max(0, 200 - existingSlot.count);
  } else if (session.account.inventory.length < session.account.backpackSize) {
    canTake = Math.min(200, obj.count);
  }
  if (canTake <= 0) return;
  const def = ctx.itemsDb.get(obj.itemId);
  const itemName = def ? stripGtColors(def.name) : `Item #${obj.itemId}`;
  if (canTake < obj.count) {
    obj.count -= canTake;
    ctx.giveInventoryItem(session, obj.itemId, canTake, true);
    ctx.dirty = true;
    const shrinkPkt = makeItemModifyObjectPacket(
      obj.uid,
      obj.itemId,
      obj.count,
      obj.x,
      obj.y,
      obj.flags
    );
    for (const p of world.peers) p.peer.sendPacket(0, shrinkPkt, true);
    OnPlayPositioned(session, "audio/object_collect.wav");
    OnConsoleMessage(session, `Collected \`w${canTake} ${itemName}\`\`.`);
    return;
  }
  const taken = obj.count;
  world.objects.splice(idx, 1);
  if (existingSlot) {
    existingSlot.count = Math.min(200, existingSlot.count + taken);
  } else {
    session.account.inventory.push({
      itemId: obj.itemId,
      count: Math.min(200, taken),
      equipped: false
    });
  }
  ctx.dirty = true;
  ctx.savePlayersNow();
  const collectPkt = makeItemCollectPacket(session.netId, obj.uid);
  for (const p of world.peers) p.peer.sendPacket(0, collectPkt, true);
  logCctvEvent(world, session, "took", `${taken} ${itemName}`);
  OnConsoleMessage(session, `Collected \`w${taken} ${itemName}\`\`.`);
}

// server/gamePacket/player_moving.ts
function handlePlayerMoving(session, rawData, tank, ctx) {
  const world = session.world;
  if (!world || session.respawnUntil && Date.now() < session.respawnUntil || session.pullUntil && Date.now() < session.pullUntil) return;
  const nx = tank.x ?? session.x;
  const ny = tank.y ?? session.y;
  if (!Number.isFinite(nx) || !Number.isFinite(ny)) return;
  if (nx < -32 || nx > world.width * 32 + 32 || ny < -32 || ny > world.height * 32 + 32) {
    OnSetPos(session, session.x, session.y);
    return;
  }
  const oldX = session.x, oldY = session.y;
  session.x = nx;
  session.y = ny;
  if (session.brb && (nx !== oldX || ny !== oldY)) {
    session.brb = false;
    broadcastIconState(world, session, 0, true);
  }
  const flags = tank.flags ?? 0;
  session.facingLeft = (flags & TANK_FLAG_FACING_LEFT) !== 0;
  const now = Date.now();
  const diedToHazard = ctx ? processMovementHazard(ctx, session, flags, oldX, oldY, now) : false;
  if (!diedToHazard) {
    tickSessionHazardRegen(session, now);
  }
  if (ctx && session.account.inventory.some((s) => s.itemId === 2204 && s.equipped)) {
    const hasIrradiated = (session.account.playmods || []).some((m) => m.id === "irradiated" && m.expiresAt > now);
    if (!hasIrradiated) {
      if (!world.geigerTarget) {
        world.geigerTarget = {
          x: Math.floor(Math.random() * (world.width - 4) + 2) * 32,
          y: Math.floor(Math.random() * (world.height - 10) + 2) * 32
        };
      }
      if (now - (session.lastGeigerPingAt || 0) > 1500) {
        session.lastGeigerPingAt = now;
        const diff = Math.hypot(session.x - world.geigerTarget.x, session.y - world.geigerTarget.y) / 32;
        if (diff <= 1) {
          ctx.consumeInventoryItem(session, 2204, 1, true);
          ctx.giveInventoryItem(session, 2286, 1, true);
          const prizeId = GTPS3_GEIGER_REWARDS[Math.floor(Math.random() * GTPS3_GEIGER_REWARDS.length)];
          ctx.giveInventoryItem(session, prizeId, 1, true);
          if (!session.account.playmods) session.account.playmods = [];
          session.account.playmods.push({ id: "irradiated", expiresAt: now + 30 * 60 * 1e3 });
          ctx.savePlayersNow();
          world.geigerTarget = {
            x: Math.floor(Math.random() * (world.width - 4) + 2) * 32,
            y: Math.floor(Math.random() * (world.height - 10) + 2) * 32
          };
          OnPlayPositioned(session, "audio/dialog_confirm.wav");
          const prizeDef = ctx.itemsDb.get(prizeId);
          const prizeName = prizeDef ? prizeDef.name : "Prize";
          OnTalkBubble(session, session.netId, `\`2Found radiation! You got \`$${prizeName}\`\`!`, 0, true);
          OnConsoleMessage(session, "You are aglow with radiation! (`$Irradiated`` mod added, `$30 mins`` left)");
        } else {
          OnPlayPositioned(session, "audio/geiger_click.wav");
        }
      }
    }
  }
  if (world.peers.size > 1) {
    const relay = Buffer.from(rawData);
    relay.writeInt32LE(session.netId, 4 + 4);
    if (session.invis) {
      const stateOff = 4 + 12;
      const bits = relay.readUInt32LE(stateOff) | INVIS_STATE_BITS;
      relay.writeUInt32LE(bits >>> 0, stateOff);
    }
    for (const other2 of world.peers) {
      if (other2 !== session) {
        other2.peer.sendPacket(0, relay, false);
      }
    }
  }
}

